import torch, triton
import triton.language as tl


@triton.jit
def k_dot(A, B, C, M, K, E, BM: tl.constexpr, BK: tl.constexpr, BE: tl.constexpr,
          NT: tl.constexpr, STORE: tl.constexpr):
    rm = tl.arange(0, BM)
    re = tl.arange(0, BE)
    acc = tl.zeros([BM, BE], dtype=tl.float32)
    for t in tl.static_range(NT):
        ck = t * BK + tl.arange(0, BK)
        a = tl.load(A + rm[:, None] * K + ck[None, :], mask=rm[:, None] < M, other=0.0)
        b = tl.load(B + ck[:, None] * E + re[None, :])
        acc += tl.dot(a, b)
    if STORE:
        tl.store(C + rm[:, None] * E + re[None, :], acc, mask=rm[:, None] < M)
    else:
        tl.store(C + rm * E, tl.sum(acc, axis=1), mask=rm < M)


